update public.ce_course2_catalog set metadata='{"id": "1047241", "title": "Uncommon but Catastrophic Anesthesia Events", "credits": 20.0, "approval_statement": "This program has been prior approved by the American Association of Nurse Anesthesiology for 20.00 MAC Ed CE credits; Code Number 1047241; Expiration Date 9/30/2029.", "pharmacology_statement": "The American Association of Nurse Anesthesiology designates this program as meeting the criteria for up to 10.50 CE credits in Pharmacology & Therapeutics.", "pain_statement": "The American Association of Nurse Anesthesiology designates this program as meeting the criteria for up to 1.00 CE credits in Pain Management.", "starts": "2026-10-01", "expires": "2029-09-30", "contact": "info@cehalo.com", "module": {"id": "course_2_module_1", "number": 1, "title": "Brain Death & Organ Procurement: BD/DNC, DBD, DCD, and NRP", "short_title": "Brain Death and Organ Procurement", "credits": 1.5, "pharmacology_credits": 1.0, "pain_credits": 0.0, "objectives": ["Define brain death / death by neurologic criteria (BD/DNC) and distinguish it from coma, persistent vegetative state, and circulatory death, applying the 2023 AAN/AAP/CNS/SCCM multi-society consensus practice guideline.", "Summarize the prerequisites, examination components, apnea testing requirements, and indications for ancillary testing that comprise current U.S. BD/DNC determination in adults and pediatric patients.", "Describe the pathophysiologic changes that occur after brain death — including the catecholamine surge, vasoplegia, diabetes insipidus, endocrine failure, and coagulopathy — and explain how each threatens transplantable organ viability.", "Identify the CRNA''s role in donor optimization, intraoperative management during organ procurement, and interprofessional coordination across ICU, OR, and organ procurement organization (OPO) teams.", "Compare donation after brain death (DBD) and donation after circulatory death (DCD), including workflow, hemodynamic patterns, ethical safeguards, warm ischemia terminology, and preservation-time considerations.", "Anticipate and titrate the hormone therapy, vasoactive infusions, electrolyte replacement, and other medications commonly required during donor care and procurement, applying 2023 RCT-level evidence on selective (rather than routine) IV levothyroxine use.", "Explain the anesthetic and procedural implications of thoracoabdominal normothermic regional perfusion (TA-NRP) and abdominal NRP (A-NRP), including anticoagulation, cerebral-circulation exclusion, perfusionist coordination, and the CRNA''s role during ECMO-supported in situ organ recovery.", "Apply protocol-based hemodynamic, endocrine, ventilatory, temperature, metabolic, and documentation strategies to donor management, using contemporary outcomes evidence (DONORS trial, UNOS NRP registries, multicenter Perioperative Outcomes Group analyses)."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module1", "page_count": 28, "document_sha256": "ac399f11c7707d7020cbbcb61e048b3ea1ca853711120cf45f64cdf6dcfc86a4", "content_status": "provider_authorized_final"}, "modules": [{"id": "course_2_module_1", "number": 1, "title": "Brain Death & Organ Procurement: BD/DNC, DBD, DCD, and NRP", "short_title": "Brain Death and Organ Procurement", "credits": 1.5, "pharmacology_credits": 1.0, "pain_credits": 0.0, "objectives": ["Define brain death / death by neurologic criteria (BD/DNC) and distinguish it from coma, persistent vegetative state, and circulatory death, applying the 2023 AAN/AAP/CNS/SCCM multi-society consensus practice guideline.", "Summarize the prerequisites, examination components, apnea testing requirements, and indications for ancillary testing that comprise current U.S. BD/DNC determination in adults and pediatric patients.", "Describe the pathophysiologic changes that occur after brain death — including the catecholamine surge, vasoplegia, diabetes insipidus, endocrine failure, and coagulopathy — and explain how each threatens transplantable organ viability.", "Identify the CRNA''s role in donor optimization, intraoperative management during organ procurement, and interprofessional coordination across ICU, OR, and organ procurement organization (OPO) teams.", "Compare donation after brain death (DBD) and donation after circulatory death (DCD), including workflow, hemodynamic patterns, ethical safeguards, warm ischemia terminology, and preservation-time considerations.", "Anticipate and titrate the hormone therapy, vasoactive infusions, electrolyte replacement, and other medications commonly required during donor care and procurement, applying 2023 RCT-level evidence on selective (rather than routine) IV levothyroxine use.", "Explain the anesthetic and procedural implications of thoracoabdominal normothermic regional perfusion (TA-NRP) and abdominal NRP (A-NRP), including anticoagulation, cerebral-circulation exclusion, perfusionist coordination, and the CRNA''s role during ECMO-supported in situ organ recovery.", "Apply protocol-based hemodynamic, endocrine, ventilatory, temperature, metabolic, and documentation strategies to donor management, using contemporary outcomes evidence (DONORS trial, UNOS NRP registries, multicenter Perioperative Outcomes Group analyses)."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module1", "page_count": 28, "document_sha256": "ac399f11c7707d7020cbbcb61e048b3ea1ca853711120cf45f64cdf6dcfc86a4", "content_status": "provider_authorized_final"}, {"id": "course_2_module_2", "number": 2, "title": "Jehovah''s Witness Anesthesia: Blood Refusal, Bloodless Medicine, and Ethical Perioperative Care", "short_title": "Jehovah’s Witness Anesthesia", "credits": 1.5, "pharmacology_credits": 0.5, "pain_credits": 0.0, "objectives": ["Summarize the core Jehovah''s Witness (JW) beliefs about blood, the categorical distinction between primary blood components and minor fractions, and the range of personal decisions a JW patient may make about specific products, techniques, and autologous circuits.", "Conduct a structured preoperative JW consultation — including advance directive review, product-by-product acceptability documentation, hospital liaison committee involvement, and interdisciplinary planning — that protects patient autonomy and reduces intraoperative decision friction.", "Apply the four pillars of Patient Blood Management (PBM) to the JW patient: treatment of preoperative anemia and iron deficiency, minimization of surgical blood loss, optimization of physiologic tolerance of anemia, and goal-directed decision-making about products the patient has accepted.", "Describe the pharmacology, dosing, and clinical role of the JW-relevant hemostatic and hematinic agents — including tranexamic acid, IV iron formulations, erythropoiesis-stimulating agents, fibrinogen concentrate, prothrombin complex concentrate, recombinant factor VIIa, desmopressin, and topical hemostatics — recognizing which are universally acceptable and which require patient-specific consent.", "Explain acceptable and unacceptable intraoperative blood-conservation techniques — including acute normovolemic hemodilution (ANH) with a continuous circuit, intraoperative cell salvage, controlled hypotension, temperature management, meticulous surgical hemostasis, and point-of-care coagulation testing — and confirm each with the patient in advance.", "Discuss the U.S. legal and ethical framework governing an adult JW''s right to refuse blood, the physician''s obligation to honor a competent adult refusal, and the JW.ORG-supplied advance directive tool the patient can carry.", "Analyze the special legal and ethical considerations that arise when a pediatric JW patient or a pregnant JW patient requires life-threatening transfusion, including parental refusal, court-ordered transfusion procedures, adolescent capacity evaluation, and the 2025 Wheeler & Formstone judicial-response review of pediatric English case law.", "Recognize the anesthetic management principles for critical bleeding in a JW patient — including permissive anemia, oxygen-delivery optimization, vasopressor and methylene-blue rescue algorithms, ICU-level monitoring, and outcome expectations informed by the Gemelli et al. (2024) 780-patient JW cardiac-surgery meta-analysis."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module2", "page_count": 27, "document_sha256": "4f676a58615653683b36cf6b15779a8a82614c1ee8a021487d2e3c547bbe1cc7", "content_status": "provider_authorized_final"}, {"id": "course_2_module_3", "number": 3, "title": "Pheochromocytoma: Diagnosis, Perioperative Optimization, and Intraoperative Anesthetic Management", "short_title": "Pheochromocytoma", "credits": 2.0, "pharmacology_credits": 1.5, "pain_credits": 0.0, "objectives": ["Define pheochromocytoma and paraganglioma (PPGL), describe the catecholamine-driven pathophysiology, and explain why chronic vasoconstriction, catecholamine cardiomyopathy, and volume contraction make these tumors a perioperative high-risk state for the CRNA.", "Identify the clinical features, epidemiology, and hereditary syndromes (MEN2, VHL, NF1, SDHx, and other 20+ known susceptibility genes) that should raise suspicion for PPGL, and describe when biochemical and genetic screening are indicated.", "Describe the recommended biochemical (plasma free metanephrines or 24-hour urinary fractionated metanephrines) and imaging (CT/MRI plus functional imaging when indicated) approaches used to confirm and localize PPGL.", "Summarize definitive treatment options — including minimally invasive and open adrenalectomy, expanding robotic experience, and emerging systemic therapies for metastatic disease (belzutifan HIF-2α inhibition, MIBG-based therapy, targeted kinase inhibitors) — and explain the goals, timing, and endpoints of preoperative medical optimization.", "Contrast the pharmacology, dosing, and clinical trade-offs of phenoxybenzamine (nonselective) versus doxazosin/prazosin/terazosin (selective alpha-1) blockade in light of the PRESCRIPT randomized trial (Buitenwerf 2020) and the Vorselaars 2022 crossover phenylephrine-test study; explain when beta blockade, calcium channel blockers, metyrosine, and magnesium sulfate are added to the preoperative regimen.", "Apply evidence-based anesthetic management principles for the preoperative, intraoperative, and immediate postoperative phases — including invasive monitoring, vascular access, choice of induction and maintenance agents, avoidance of catecholamine-releasing or histamine-releasing drugs, and phase-specific readiness at induction, insufflation, tumor manipulation, and adrenal vein ligation.", "Anticipate and manage the two dominant hemodynamic emergencies of PPGL resection: catecholamine-driven hypertensive crisis (sodium nitroprusside, nicardipine, clevidipine, phentolamine, nitroglycerin, esmolol, magnesium sulfate) and post-resection vasodilatory hypotension (norepinephrine, phenylephrine, vasopressin, epinephrine, judicious volume) — including choice, sequencing, and endpoint monitoring.", "Recognize the intraoperative presentation of an undiagnosed pheochromocytoma during a nonadrenal case, execute the CRNA immediate-action bundle (deepen anesthesia, invasive monitoring, short-acting vasodilators, cautious beta blockade, magnesium adjunct, consider aborting elective surgery), and plan ICU-level postoperative care and endocrine referral.", "Identify common postoperative complications — recurrent hypertension, arrhythmias, myocardial ischemia, prolonged vasopressor requirement, hypoglycemia from rebound insulin, adrenal insufficiency in bilateral cases — and describe long-term follow-up including lifelong biochemical surveillance and hereditary counseling per the Endocrine Society guideline (Lenders 2014, endorsed through 2025)."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module3", "page_count": 32, "document_sha256": "aee3aeae77c52d6c8e988b0a90e75f0e2b5871c2605becb8412bc918223aa810", "content_status": "provider_authorized_final"}, {"id": "course_2_module_4", "number": 4, "title": "Von Willebrand Disease: Perioperative Hemostasis and Anesthetic Management", "short_title": "Von Willebrand Disease", "credits": 2.0, "pharmacology_credits": 2.0, "pain_credits": 0.0, "objectives": ["Differentiate the major types of von Willebrand disease (Type 1, Type 2A, 2B, 2M, 2N, Type 3, and acquired von Willebrand syndrome) and explain how subtype-specific defects in von Willebrand factor (VWF) quantity, multimer distribution, platelet binding, and factor VIII (FVIII) binding affect perioperative bleeding risk and product selection.", "Identify the key elements of the CRNA preanesthetic evaluation for known or suspected VWD, including validated bleeding-assessment tools (ISTH-BAT), personal and family bleeding history, prior procedural outcomes, medication reconciliation for antiplatelet and SSRI exposure, and interpretation of VWF antigen, VWF activity (ristocetin cofactor/GPIbM/GPIbR), and FVIII activity.", "Compare the perioperative roles, mechanism, dosing, monitoring, and specific cautions of desmopressin (DDAVP), tranexamic acid, and VWF-containing concentrates — including the plasma-derived products Humate-P, wilate, and Alphanate and the recombinant VWF product Vonvendi — in elective and urgent surgery, per the ASH ISTH NHF WFH 2021 guideline and its 2025 monitoring update.", "Apply the ASH 2021 evidence-based perioperative targets — VWF activity and FVIII ≥0.50 IU/mL for at least 3 consecutive days after major surgery, and VWF ≥0.50 IU/mL for minor surgery — when designing an anesthesia plan with hematology for minor procedures, major surgery, and obstetric care.", "Evaluate the risks, prerequisites, and factor-activity thresholds for neuraxial and peripheral regional techniques in patients with suspected or confirmed VWD, including the guideline factor range (50–150%) for neuraxial placement, the more conservative institutional threshold (VWF ≥100%) many programs adopt for labor epidural placement, and the deep-versus-superficial block framework.", "Apply postoperative monitoring and rescue strategies for delayed bleeding, progressive FVIII accumulation with repeated dosing of FVIII-containing concentrates, venous thromboembolism risk, and opioid-sparing multimodal pain management that avoids platelet-inhibiting NSAIDs when alternatives exist.", "Recognize situations that warrant urgent hematology consultation, higher-acuity postoperative care, or modification of the proposed procedure or anesthetic technique — including undiagnosed VWD presenting as unexpected surgical hemorrhage, acquired VWS in aortic stenosis (Heyde syndrome), LVAD support, or lymphoproliferative disease, and the pregnant VWD patient at term."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module4", "page_count": 34, "document_sha256": "0e8cbf485fabed76af9ffc253cfa00db76461a7f0731cb0c1c409de70cccc15d", "content_status": "provider_authorized_final"}, {"id": "course_2_module_5", "number": 5, "title": "Serotonin Syndrome: Perioperative Recognition, Prevention, and Management", "short_title": "Serotonin Syndrome", "credits": 2.0, "pharmacology_credits": 1.0, "pain_credits": 0.0, "objectives": ["Define serotonin syndrome (serotonin toxicity), describe its clinical spectrum from mild to life-threatening, and explain why it is a high-priority perioperative diagnosis for the CRNA.", "Describe the pathophysiology of serotonin excess, including the roles of 5-HT1A and 5-HT2A receptors, mechanisms of increased synaptic serotonin (reuptake inhibition, monoamine oxidase inhibition, direct agonism, increased release, and impaired clearance), and the pharmacokinetic reasons that fluoxetine and other long-half-life agents may prolong toxicity.", "Identify the outpatient medication classes (MAOIs, SSRIs, SNRIs, TCAs, trazodone, buspirone, lithium, St. John''s wort, dextromethorphan, MDMA) and the perioperative agents (methylene blue, linezolid, meperidine, tramadol, methadone, fentanyl, metoclopramide, ondansetron) that precipitate serotonin syndrome, and grade the relative risk of each class in monotherapy versus combination.", "Recognize the clinical triad of altered mental status, autonomic instability, and neuromuscular hyperactivity, with particular attention to inducible clonus, spontaneous clonus, ocular clonus, and lower-extremity hyperreflexia as the highest-yield examination findings.", "Apply the Hunter Serotonin Toxicity Criteria at the bedside and differentiate serotonin syndrome from malignant hyperthermia, neuroleptic malignant syndrome, anticholinergic toxicity, thyroid storm, sepsis, stimulant intoxication, and withdrawal syndromes.", "Outline severity-based management for mild, moderate, and severe serotonin syndrome — including discontinuation of offending agents, benzodiazepine sedation, active external cooling, avoidance of antipyretics, avoidance of succinylcholine when hyperkalemia or rhabdomyolysis is a concern, and airway control with nondepolarizing paralysis for refractory rigidity or hyperthermia.", "Evaluate the current low-quality evidence for cyproheptadine, describe when it may be considered as adjunctive therapy, and explain why supportive care remains the foundation of treatment per the 2024 Chiew and Isbister BJCP review.", "Incorporate prevention strategies into everyday CRNA practice — including a focused medication reconciliation for serotonergic agents, avoidance of high-risk perioperative combinations (SSRI/SNRI + methylene blue, MAOI + meperidine, SSRI + tramadol), preferential use of morphine or hydromorphone in high-risk patients, and structured handoff communication in the PACU and ICU."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module5", "page_count": 30, "document_sha256": "db4e808c371b1517b4ca28fbc08fa7c9af54bea7b6443fef24c47b07f2a7f0e3", "content_status": "provider_authorized_final"}, {"id": "course_2_module_6", "number": 6, "title": "Fire Safety and Fire Prevention in the Operating Room", "short_title": "OR Fire Safety", "credits": 1.5, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Describe the three elements of the surgical fire triad — oxidizer, ignition source, and fuel — and explain how each is generated or controlled by members of the perioperative team.", "Identify patient, procedure, and environmental factors that elevate the risk of an operating room fire, including head/face/neck/upper-chest surgery, MAC with open oxygen delivery, airway procedures, and electrocautery use near oxidizer-enriched fields.", "Recognize the common flammable liquids and fuel sources encountered in the OR, including alcohol-based skin antiseptics (ChloraPrep, DuraPrep, 3M SoluPrep), alcohol-containing iodophors, tinctures, adhesive removers, drapes, sponges, tracheal tubes, and patient hair.", "Apply evidence-based prevention strategies for oxygen management (target FiO2 ≤30% by open delivery in high-risk cases, secure the airway when higher concentrations are needed, avoid nitrous oxide, use air-oxygen blends, allow oxygen to dissipate before ignition source activation) and prep-solution management (verify complete drying, avoid pooling in hair/skin folds/linens, use appropriate applicator size).", "Explain the CRNA''s role in the pre-procedure fire risk assessment and surgical time-out, including announcing changes in oxygen concentration, confirming prep-dry status, and coordinating with the surgeon before electrocautery or laser activation.", "Outline the immediate coordinated response to a fire on the patient, in the airway, or in the room — including the CRNA''s priority action of discontinuing oxygen and nitrous oxide, and the correct sequence of the seven-step surgical fire response algorithm within the first 60 seconds.", "Distinguish the surgical fire response (announce → stop oxidizer → stop ignition → remove fuel → extinguish → re-establish ventilation → report) from the RACE facility fire model and the PASS mnemonic for extinguisher use, and explain when each applies.", "Discuss post-event management, including bronchoscopy after airway fires, burn and inhalation-injury assessment, event documentation, institutional reporting, structured debriefing, and systems improvement through drills and simulation."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module6", "page_count": 24, "document_sha256": "802fb540d56bfee05c828f3c9680f64471c1a7c9d45b24f7ca5f0394d85e4f46", "content_status": "provider_authorized_final"}, {"id": "course_2_module_7", "number": 7, "title": "Negative Pressure Pulmonary Edema (NPPE)", "short_title": "Negative Pressure Pulmonary Edema", "credits": 2.0, "pharmacology_credits": 1.0, "pain_credits": 0.0, "objectives": ["Define negative pressure pulmonary edema (NPPE), distinguish it from cardiogenic pulmonary edema, and place it within the differential diagnosis of acute postoperative hypoxemia.", "Explain the hydrostatic and permeability mechanisms by which markedly negative intrathoracic pressure produces alveolar and interstitial edema after upper airway obstruction, including the roles of increased venous return, elevated pulmonary capillary hydrostatic pressure, sympathetic surge, and transient alveolar-capillary membrane stress.", "Differentiate Type I NPPE (acute obstruction — for example, laryngospasm after extubation) from Type II NPPE (after relief of chronic upper airway obstruction) and identify perioperative risk factors including young athletic adults, head and neck surgery, obstructive sleep apnea, obesity, and airway pathology.", "Recognize the clinical and radiographic presentation of NPPE — tachypnea, hypoxemia, crackles, frothy or pink sputum, and diffuse bilateral infiltrates — and apply a structured differential diagnosis that includes aspiration, cardiogenic edema, fluid overload, residual neuromuscular blockade, bronchospasm, anaphylaxis, and pulmonary embolism.", "Apply an evidence-based treatment algorithm centered on relief of the airway obstruction, 100% oxygen, positive-pressure ventilation (CPAP / noninvasive positive-pressure ventilation for mild cases and tracheal intubation with PEEP for severe cases), and thoughtful use of adjuncts including furosemide and bronchodilators.", "Describe the pharmacology of the two most important rescue medications used when laryngospasm precipitates NPPE — propofol for deepening anesthesia and succinylcholine for breaking persistent laryngospasm — including doses, onset, and adverse effects (hyperkalemia, bradycardia, malignant hyperthermia trigger, prolonged paralysis with pseudocholinesterase deficiency, and pediatric considerations).", "Execute the seven-step laryngospasm treatment algorithm within the first minute of an obstructive event and prioritize the CRNA''s role in smooth emergence, adequate reversal of neuromuscular blockade, and early recognition of the peri-extubation obstruction that most often precedes NPPE.", "Discuss post-treatment monitoring and disposition, including chest imaging, arterial blood gas indications, ICU escalation criteria, and typical resolution within 12 to 24 hours after obstruction relief and supportive care."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module7", "page_count": 25, "document_sha256": "36ee7a13cae6accc31fc44431590e8afa9baf872a445f2672db14d290af5d20e", "content_status": "provider_authorized_final"}, {"id": "course_2_module_8", "number": 8, "title": "Amniotic Fluid Embolism (AFE)", "short_title": "Amniotic Fluid Embolism", "credits": 2.5, "pharmacology_credits": 1.0, "pain_credits": 0.0, "objectives": ["Define amniotic fluid embolism (AFE) and describe its epidemiology, timing, incidence, mortality, and clinical significance for CRNA practice.", "Explain the pathophysiology of AFE, including pulmonary vascular obstruction, right ventricular failure, inflammatory activation, hemodynamic collapse, and disseminated intravascular coagulation.", "Distinguish the two clinical phases of AFE (Phase 1 cardiopulmonary collapse and Phase 2 hemostatic failure) and their implications for CRNA management priorities.", "Identify disseminated intravascular coagulation (DIC) associated with AFE and describe protocolized CRNA management including massive transfusion, fibrinogen replacement, and viscoelastic-guided therapy.", "Recognize reported risk-factor associations for AFE and understand why risk factors inform preparedness rather than reliable prediction.", "Apply diagnostic criteria for suspected AFE, including the Clark consensus criteria, while acknowledging that AFE is a clinical diagnosis of exclusion.", "Construct a rapid differential diagnosis for peripartum collapse, including hemorrhage, high spinal, LAST, anaphylaxis, PE, VAE, eclampsia, sepsis, aspiration, and cardiac disease.", "Perform immediate CRNA management of suspected AFE, including airway control, high-quality CPR with pregnancy modifications, manual uterine displacement, and activation of the obstetric emergency response.", "Implement advanced management of AFE including vasopressor and inotrope selection, right-ventricular support, inhaled pulmonary vasodilators, and consideration of ECMO for refractory shock.", "Coordinate perimortem cesarean delivery (resuscitative hysterotomy) and interprofessional obstetric emergency response.", "Discuss short-term and long-term maternal and neonatal outcomes after AFE, including morbidity, mortality, and psychological sequelae.", "Apply case-based reasoning to suspected AFE scenarios during labor, cesarean delivery, and the immediate postpartum period.", "Describe the AFE Registry and Biorepository and the CRNA''s role in specimen preservation without interrupting resuscitation.", "Execute post-event responsibilities including ICU handoff, documentation, family communication, debriefing, and quality-improvement follow-through."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module8", "page_count": 34, "document_sha256": "5ef8e488a1855dcf8e6b4fbe7801c066e35a5065bd476b64d4205455906506b5", "content_status": "provider_authorized_final"}, {"id": "course_2_module_9", "number": 9, "title": "Local Anesthetic Systemic Toxicity (LAST)", "short_title": "Local Anesthetic Systemic Toxicity", "credits": 2.0, "pharmacology_credits": 1.0, "pain_credits": 1.0, "objectives": ["Describe the epidemiology and clinical significance of local anesthetic systemic toxicity (LAST) across perioperative, obstetric, procedural, and non-operating room environments.", "Explain how local anesthetic pharmacology — including sodium channel blockade, lipid solubility, protein binding, pKa, and metabolism — contributes to central nervous system and cardiovascular toxicity.", "Differentiate amide from ester local anesthetics and describe how cumulative dosing, additive systemic toxicity, and physiologic state influence LAST susceptibility.", "Identify patient-, drug-, dose-, and procedure-related risk factors for LAST, including fascial plane blocks, continuous catheters, IV lidocaine infusions, and liposomal bupivacaine.", "Differentiate early neurologic findings from cardiovascular manifestations and atypical or masked presentations of LAST.", "Apply the ASRA 2020 LAST checklist principles for immediate CRNA management: airway support, seizure suppression with benzodiazepines, modified advanced cardiac life support, and early 20% lipid emulsion.", "Calculate 20% lipid emulsion bolus and infusion dosing for adults under 70 kg and 70 kg or greater, including escalation, cumulative dose limits, and post-stabilization monitoring.", "Modify advanced cardiac life support for LAST: use small-dose epinephrine, prefer amiodarone over lidocaine, and avoid vasopressin, beta-blockers, and calcium channel blockers.", "Use recommended maximum local anesthetic dose limits as an upper boundary — not a target — and reduce doses for high-risk patients and high-vascularity injection sites.", "Construct a rapid differential diagnosis for peri-injection collapse including high spinal, intravascular epinephrine, anaphylaxis, methemoglobinemia, seizure, cardiac event, and medication error.", "Develop prevention plans for regional anesthesia, fascial plane blocks, infiltration anesthesia, topical airway anesthesia, and continuous local anesthetic infusions, including cumulative dose tracking and handoff communication.", "Coordinate the LAST response as a team leader: role assignment, cognitive aid use, communication with surgical/procedural teams, and escalation to ECMO or expert consultation when needed.", "Apply case-based reasoning to LAST scenarios including early CNS toxicity from peripheral nerve blocks, cardiovascular collapse under sedation, and delayed LAST from IV lidocaine infusions.", "Execute post-event responsibilities including monitored observation, documentation, structured handoff, family communication, debriefing, and quality-improvement follow-through."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module9", "page_count": 36, "document_sha256": "afe155d5b1c7f0cf9058f8200b710c63e176f92241eeafdb972e7db048497a33", "content_status": "provider_authorized_final"}, {"id": "course_2_module_10", "number": 10, "title": "Malignant Hyperthermia (MH)", "short_title": "Malignant Hyperthermia", "credits": 3.0, "pharmacology_credits": 1.5, "pain_credits": 0.0, "objectives": ["Describe the genetic and pathophysiologic basis of malignant hyperthermia (MH), including RYR1, CACNA1S, and STAC3 variants and sarcoplasmic reticulum calcium dysregulation.", "Identify all recognized MH triggering anesthetic agents and list non-triggering (MH-safe) agents and techniques appropriate for MH-susceptible patients.", "Recognize the earliest clinical and monitored signs of an intraoperative MH crisis, including unexplained rise in end-tidal carbon dioxide, sinus tachycardia, masseter spasm, and mixed acidosis.", "Formulate a stepwise Malignant Hyperthermia Association of the United States (MHAUS) emergency response, including hotline activation, discontinuation of triggers, hyperventilation, and dantrolene administration.", "Calculate weight-based dantrolene dosing and compare reconstitution and administration of traditional dantrolene 20 mg vials with Ryanodex 250 mg vials.", "Implement adjunctive pharmacologic and physiologic management for MH, including treatment of hyperkalemia, acidosis, dysrhythmias, and hyperthermia, while avoiding calcium channel blockers.", "Evaluate the differential diagnosis for intraoperative hypermetabolism and distinguish MH from thyroid storm, sepsis, pheochromocytoma, and neuroleptic malignant syndrome.", "Coordinate post-crisis care, including ICU-level monitoring, continued dantrolene therapy, surveillance for recrudescence, and referral of the patient and biologic family for MH testing at an MHAUS-recognized center.", "Develop a comprehensive anesthetic plan for an MH-susceptible patient, including preoperative assessment, anesthesia machine preparation, non-triggering total intravenous anesthesia or regional technique, and PACU disposition.", "Apply case-based reasoning to classic intraoperative MH, ambulatory surgery center MH, and delayed postoperative MH with recrudescence, and confirm minimum dantrolene stocking at every anesthetizing location."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 31, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course2_module10", "page_count": 35, "document_sha256": "983bc7dbc3c0517be41413f49509a0ddd6e4b38a4cb21fb73747e830add51952", "content_status": "provider_authorized_final"}], "course_id": "1047241", "course_number": 2, "total_credits": 20, "pharmacology_credits": 10.5, "pain_credits": 1, "required_modules": 10, "purchases_enabled": false, "released": false}'::jsonb where id='1047241';